--region define
local FilterTypes = {
    All           = 0,  -- 全部
    StoreManager  = 1,  -- 店长  等同于卡牌经营状态表 job
    StoreStaff    = 2,  -- 店员  等同于卡牌经营状态表 job
    Takeaway      = 3,  -- 外卖  等同于卡牌经营状态表 job
}

