--region init

function OverManegeLoungeSelectCards:Init(selectIndex)
    self:InitAction()
    self:InitData(selectIndex)

    self:InitFilterNode()
end


function OverManegeLoungeSelectCards:InitAction()

end

function OverManegeLoungeSelectCards:InitData(selectIndex)
    local dataProviderIns = DataProvider:GetInstance()
    local cards           = dataProviderIns:GetCards()

    local function GetPriority(cardDojo)
        local playerCardId = checkNumber(cardDojo.id)
        local cardInfo     = dataProviderIns:GetCardInfoByPlayerCardId(playerCardId)
        if cardInfo then
            return cardInfo.cafeEnergy >= cardInfo.maxEnergy and 2 or 1
        end
        return 0
    end

    --- 在房间里休息的，和休息完成的需要显示的。这里排序是休息完成>休息中的>其他，其他按照心情值升序排序
    table.sort(cards, function(a, b)
        local aPriority = GetPriority(a)
        local bPriority = GetPriority(b)
        if aPriority ~= bPriority then
            return aPriority > bPriority
        end
        if a.cafeEnergy ~= b.cafeEnergy then
            return a.cafeEnergy < b.cafeEnergy
        end
        return checkNumber(a.cardId) < checkNumber( b.cardId)
    end)

    self._selectIndex     = selectIndex
    self._cards           = cards
    self._dataProviderIns = dataProviderIns

end

function OverManegeLoungeSelectCards:InitFilterNode()
    ---@type UICommonFilterMB
    local filterNodeEnv = CfUtils.GetLuaScr(self.CommonFilterNode, "Game.Behaviours.UICommonFilterMB")
    filterNodeEnv:SetPageType(Constants.UIFilterPageType.PullUP)
    local filterData = {
        {conditionType = FilterTypes.All,          typeDesc = localize('全部')},
        {conditionType = FilterTypes.StoreManager, typeDesc = localize('店长')},
        {conditionType = FilterTypes.StoreStaff,   typeDesc = localize('店员')},
        {conditionType = FilterTypes.Takeaway,     typeDesc = localize('外卖')},
    }
    filterNodeEnv:InitSortTypeData(filterData)
    filterNodeEnv:SetCallback({}, function()
        local selectIndex  = filterNodeEnv.selectIndex
        local sortTypeData = filterNodeEnv.sortTypeList[selectIndex]
        self:SetFilterType(sortTypeData.conditionType)
        --print("->>>>>>")
    end)
    filterNodeEnv:SetStyleType(2) -- 1：黑色，2：白色
    filterNodeEnv:RefreshAlignNode(filterData[filterNodeEnv.selectIndex])
    self:SetFilterType(self:GetFilterType())

    self._filterNodeEnv = filterNodeEnv
end


--endregion


--region logic

function OverManegeLoungeSelectCards:FreshUI()
    local loungeData = self._dataProviderIns:GetLoungeDataByIndex(self._selectIndex)
    self.TextNumber.text = string.format("<size=60><color=#FFFFFF>%s</size></color>/%s", loungeData.cardCount, self._dataProviderIns:GetLoungeCapacity())
end

function OverManegeLoungeSelectCards:UpdateFilterType()
    local cardDataList = {}

    local filterType = self:GetFilterType()
    
    --local cards      = cardComp:GetAllCardTable()

    for i, v in ipairs(self._cards) do
        if filterType == FilterTypes.All then
            v.cafeEnergy = checkNumber(v.cafeEnergy)
            tInsert(cardDataList, v)
        else
            local vo = MaidCoffeeUtils.GetCardManagerInfoVo(v.cardId)
            for _, job in ipairs(vo.job) do
                if checkNumber(job) == filterType then
                    v.cafeEnergy = checkNumber(v.cafeEnergy)
                    tInsert(cardDataList, v)
                end
            end
        end
    end

    self._cardDataList = cardDataList
    -- update List
    self:FreshList_()
end

function OverManegeLoungeSelectCards:FreshList_()
    local ScrollView = self.ScrollView
    local count      = #self._cardDataList
    if not ScrollView.IsListViewInit then
        ScrollView:InitListView(count, Bind(self, self.OnGetItemByIndex_))
    else
        GameUtils.ReloadData(ScrollView, count)
    end
end

function OverManegeLoungeSelectCards:OnGetItemByIndex_(listView, index, row, column)
    if index < 0 then return nil end
    local cell = listView:NewListViewItem(Cell)

    local cellViewMB = GetLuaBehaviour(cell.gameObject, LoungeSelectCardsCellPath)
    ---@type OverManegeLoungeSelectCardsCell
    local mbEnv = cellViewMB.Env
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        if cellViewMB.Env == nil then
            cellViewMB:Init()
        end
        mbEnv = cellViewMB.Env
        mbEnv:SetCallback(Bind(self, self.OnClickCellAction))
    end


    if mbEnv == nil then return end
    local pos = index + 1
    ---@type CardDojo
    local cardDojo = self._cardDataList[pos]
    local isInLounge = self._dataProviderIns:GetCardInfoByPlayerCardId(checkNumber(cardDojo.id)) ~= nil
    mbEnv:FreshUI(self._cardDataList[pos], isInLounge, pos)

    return cell
end

--endregion


--region get/set
function OverManegeLoungeSelectCards:GetFilterType()
    return checkInt(self._filterType)
end
function OverManegeLoungeSelectCards:SetFilterType(type)
    self._filterType = checkInt(type)
    self:UpdateFilterType()
end
--endregion


--region handler

function OverManegeLoungeSelectCards:OnClickCellAction(index)
    local cardDojo     = self._cardDataList[index]
    local playerCardId = checkNumber(cardDojo.id)
    local dataProviderIns = self._dataProviderIns
    local cardInfo     = dataProviderIns:GetCardInfoByPlayerCardId(playerCardId)

    local loungeIndex, roomId, cardIds, changeIds, isAdd
    if cardInfo then
        loungeIndex = dataProviderIns:GetLoungeIndexByCardId(playerCardId)
        local loungeData  = dataProviderIns:GetLoungeDataByIndex(loungeIndex)
        cardIds     = {}
        for i, v in ipairs(loungeData.playerCardIds) do
            tInsert(cardIds, v == playerCardId and 0 or v)
        end
        roomId      = loungeData.roomId
        changeIds   = {playerCardId}
        isAdd       = false

    else
        loungeIndex = self._selectIndex
        local loungeData  = dataProviderIns:GetLoungeDataByIndex(loungeIndex)
        if loungeData.cardCount >= dataProviderIns:GetLoungeCapacity() then
            GameUtils.Toast(localize("该休息室暂无可入仓卡牌"))
            return
        end

        if dataProviderIns:CheckIsMaxEnergy(playerCardId) then
            GameUtils.Toast(localize("该卡牌心情已满"))
            return
        end
        
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        ---@type PlayerDojo
        local playerDojo = playerComponent:GetPlayerDojo()
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting4032, "WelfareSettingVo", 1)
        local isHavePrivilegeCard = playerDojo:IsHavePrivilegeCardById(tonumber(vo.giftId))
        if loungeData.vip and not isHavePrivilegeCard then
            GameUtils.Toast(localize("当前特权卡已过期"))
            return
        end

        roomId      = loungeData.roomId
        changeIds   = {playerCardId}
        isAdd       = true

        cardIds     = {}
        for i, v in ipairs(loungeData.playerCardIds) do
            if v == 0 and playerCardId > 0 then
                tInsert(cardIds, playerCardId)
                playerCardId = 0
            else
                tInsert(cardIds, v)
            end
        end

    end

    dataProviderIns:RequestLoungeUpdate(loungeIndex, roomId, cardIds, changeIds, isAdd, false, function()
        self:FreshList_()
    end)
end
--endregion

return OverManegeLoungeSelectCards